PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'free' CHECK(role IN ('free','admin')),verified INTEGER NOT NULL DEFAULT 0,disabled INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE email_verification_tokens(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE TABLE password_reset_tokens(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE TABLE subscriptions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,event_id TEXT UNIQUE,paid_through INTEGER NOT NULL,source TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX subscriptions_user_expiry ON subscriptions(user_id,paid_through);
CREATE TABLE payment_events(id TEXT PRIMARY KEY,transaction_id TEXT NOT NULL UNIQUE,event_type TEXT NOT NULL,amount TEXT NOT NULL,currency TEXT NOT NULL,member INTEGER NOT NULL,received_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',user_id TEXT REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE membership_claims(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,transaction_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL,UNIQUE(user_id,transaction_id));
CREATE TABLE user_preferences(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,data TEXT NOT NULL DEFAULT '{}',retention_days INTEGER NOT NULL DEFAULT 30 CHECK(retention_days IN (0,7,30,90)));
CREATE TABLE saved_presets(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('preset','workflow')),name TEXT NOT NULL,data TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX presets_user ON saved_presets(user_id);
CREATE TABLE tool_history(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,tool TEXT NOT NULL,data TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX history_user_date ON tool_history(user_id,created_at);
CREATE TABLE audit_logs(id TEXT PRIMARY KEY,actor_id TEXT,action TEXT NOT NULL,target_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE tool_availability(tool TEXT PRIMARY KEY,enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE usage_daily(day TEXT NOT NULL,tool TEXT NOT NULL,count INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,tool));
